fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let maxsplit = maxsplit as usize; // Convert u8 to usize for easier calculations
    // Requires: a is a vector of strings, sep is a string, and maxsplit is a non-negative integer
    // Ensures: The result is a vector of vectors of strings, where each inner vector contains the parts of the original string split by sep from the right, up to maxsplit times.
    // The length of the result is equal to the length of a.
    // Each inner vector has at most maxsplit + 1 elements.
    // The elements in each inner vector are in the order they were split.
    // The total number of parts across all inner vectors is equal to the total number of splits performed.
    let result: Vec<Vec<String>> = a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                // If maxsplit is 0, return the original string as a single-element vector
                vec![s]
            } else {
                // Perform the right-split operation
                let mut parts = Vec::new();
                let mut remaining = s;
                let mut splits = 0;

                // Invariant: splits <= maxsplit
                // Split from the right until we reach the maxsplit limit
                while splits < maxsplit {
                    if let Some(pos) = remaining.rfind(&sep) {
                        // Push the rightmost part
                        parts.push(remaining.split_off(pos));
                        // Update remaining to the left part
                        remaining = remaining[..pos].to_string();
                    } else {
                        // No more separators found, push the remaining part
                        parts.push(remaining);
                        break;
                    }
                    splits += 1;
                }

                // Push any remaining part if it's not empty
                if !remaining.is_empty() {
                    parts.push(remaining);
                }

                // Reverse the parts to maintain the right-split order
                parts.reverse();
                parts
            }
        })
        .collect();

    // Ensures: The length of the result is equal to the length of a
    assert!(result.len() == a.len());
    result
}

fn main() {
    let strings = vec![
        "one,two,three".to_string(),
        "four,five,six".to_string(),
        "seven,eight,nine".to_string(),
    ];
    let separator = ",".to_string();
    let maxsplit = 1;

    let result = rsplit(strings, separator, maxsplit);
    for res in result {
        println!("{:?}", res);
    }
}